package com.primehr.succession.domain;
import com.primehr.gap.application.TargetCompetencyGapService.*;import com.primehr.gap.domain.GapClassification;import com.primehr.integration.administrative.AdministrativePositionTarget;import com.primehr.integration.humanresource.HumanResourceAssessmentSubject;import com.primehr.positionprofile.domain.PositionTargetType;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.List;import static org.assertj.core.api.Assertions.*;
class SuccessionReadinessDomainTest{
 @Test void assessmentSnapshotsExactSourcesAndRequiresHumanRecommendationBeforeFinalization(){var candidate=candidate();var scale=scale();var assessment=new SuccessionReadinessAssessment("A",candidate,"charter",scale,gap());var level=level(scale,true);assessment.recommend(level,true,"Panel reviewed the exact competency evidence","PANEL-1",Instant.now());assertThat(assessment.getStatus()).isEqualTo(SuccessionReadinessAssessment.Status.RECOMMENDED);assessment.finalizeDecision("AGENCY-HEAD",Instant.now());assertThat(assessment.getStatus()).isEqualTo(SuccessionReadinessAssessment.Status.FINALIZED);assertThat(assessment.getPositionProfileId()).isEqualTo("target-profile");assertThat(assessment.getPersonProfileId()).isEqualTo("person-profile");}
 @Test void poolInclusionRejectsLevelThatDoesNotAllowMembership(){var candidate=candidate();var scale=scale();var assessment=new SuccessionReadinessAssessment("A",candidate,"charter",scale,gap());assertThatThrownBy(()->assessment.recommend(level(scale,false),true,"Narrative","PANEL-1",Instant.now())).isInstanceOf(IllegalArgumentException.class);}
 @Test void panelConflictRecusesAndBlocksRepeatedMutation(){var member=new SuccessionCommitteeMember("A","charter",subject("PANEL-1"),SuccessionCommitteeMember.Role.MEMBER,true,LocalDate.now().minusDays(1),null);ReflectionTestUtils.setField(member,"id","member");var assignment=new SuccessionReadinessPanelAssignment("A","assessment",member);assignment.recuse("DECLARED","Close supervisory relationship");assertThat(assignment.getStatus()).isEqualTo(SuccessionReadinessPanelAssignment.Status.RECUSED);assertThatThrownBy(()->assignment.recuse("DECLARED","Again")).isInstanceOf(IllegalLifecycleTransitionException.class);}
 private SuccessionCandidate candidate(){var x=new SuccessionCandidate("A","cycle",designation(),SuccessionCandidate.IntakeType.AUTHORIZED_NOMINATION,"HR-1",subject("EMP-1"),"Nomination");ReflectionTestUtils.setField(x,"id","candidate");x.sendNotice("HR-1","Notice",Instant.now());x.consent("EMP-1","Consent",Instant.now());x.submit("HR-1",Instant.now());x.decideEligibility(true,"PANEL-1","Eligible",Instant.now());return x;}
 private SuccessionReadinessScaleVersion scale(){var x=new SuccessionReadinessScaleVersion("A","scale",1,null,"Agency readiness scale",null,"Human decision guidance",true);ReflectionTestUtils.setField(x,"id","scale-version");return x;}
 private SuccessionReadinessLevel level(SuccessionReadinessScaleVersion scale,boolean allows){var x=new SuccessionReadinessLevel("A",scale.getId(),allows?"READY":"DEVELOPING",allows?"Ready":"Developing","Agency definition","Guidance",12,allows,1);ReflectionTestUtils.setField(x,"id",allows?"level-ready":"level-developing");return x;}
 private TargetGapResult gap(){return new TargetGapResult("target-profile",3,7,"position-fp","person-profile",2,LocalDate.now().minusMonths(1),null,Instant.now(),List.of(new TargetGapItem("requirement","competency","C1","Competency",2,"scale",1,"required","L3","Level 3",3,"attained","L2","Level 2",2,1,GapClassification.BELOW,null,"CORE","CRITICAL",1)));}
 private HumanResourceAssessmentSubject subject(String employeeNo){return new HumanResourceAssessmentSubject(1L,employeeNo,"Employee",true,10L,LocalDateTime.now(),20L,30L,"employee-fp",LocalDateTime.now(),Instant.now());}
 private SuccessionCriticalPositionDesignation designation(){var target=new AdministrativePositionTarget(PositionTargetType.JOB_POSITION,20L,20L,"Division Chief",24L,1L,null,null,"target-fp",Instant.now());var d=new SuccessionCriticalPositionDesignation("A",target,"framework",1,"framework-fp","charter","Critical Division Chief","Continuity",LocalDate.now().minusYears(1),LocalDate.now().plusYears(1));ReflectionTestUtils.setField(d,"id","designation");d.submit("maker",Instant.now());d.approve("approver","Approved",LocalDate.now().minusYears(1),null,Instant.now());return d;}
}
